  def _checkDelete(self, objsToBeDeleted, objsToBeChecked, linkCounter, topObjectsToCheck):
    """
    checkDelete for ccp.nmr.Nmr.Experiment:
       determines cascading deletes 
    to follow from delete of object.
       *Implementation function* - should 
    be called only by API delete function.
    """
    dataDict = self.__dict__
    objsToBeDeleted.add(self)
    if (not ((dataDict.get('topObject').__dict__.get('isLoaded') or dataDict.get('topObject').__dict__.get('isReading')))):
      dataDict.get('topObject').load()

    access = dataDict.get('access')
    if (access is not None):
      topObject = access.__dict__.get('topObject')
      topObjectsToCheck.add(topObject)

    citations = dataDict.get('citations')
    pass
    for citation in citations:
      topObject = citation.__dict__.get('topObject')
      topObjectsToCheck.add(topObject)

    dataSources = dataDict.get('dataSources').values()
    for dataSource in dataSources:
      if (not (dataSource in objsToBeDeleted)):
        objsToBeDeleted.add(dataSource)
        objsToBeChecked.append(dataSource)

    derivationMethod = dataDict.get('derivationMethod')
    if (derivationMethod is not None):
      topObject = derivationMethod.__dict__.get('topObject')
      topObjectsToCheck.add(topObject)

    root = dataDict.get('topObject').__dict__.get('memopsRoot')
    root.refreshTopObjects('ccp.nmr.NmrEntry')
    tobjList = root.__dict__.get('nmrEntryStores').values()
    for tobj in tobjList:
      if (not (tobj.__dict__.get('isLoaded'))):
        tobj.load()

    entries = dataDict.get('entries')
    pass
    for entry in entries:
      topObject = entry.__dict__.get('topObject')
      topObjectsToCheck.add(topObject)

    expChainStates = dataDict.get('expChainStates').values()
    for expChainState in expChainStates:
      if (not (expChainState in objsToBeDeleted)):
        objsToBeDeleted.add(expChainState)
        objsToBeChecked.append(expChainState)

    expDims = dataDict.get('expDims').values()
    for expDim in expDims:
      if (not (expDim in objsToBeDeleted)):
        objsToBeDeleted.add(expDim)
        objsToBeChecked.append(expDim)

    expTransfers = dataDict.get('expTransfers').values()
    for expTransfer in expTransfers:
      if (not (expTransfer in objsToBeDeleted)):
        objsToBeDeleted.add(expTransfer)
        objsToBeChecked.append(expTransfer)

    labeledMixtures = dataDict.get('labeledMixtures')
    pass
    for labeledMixture in labeledMixtures:
      topObject = labeledMixture.__dict__.get('topObject')
      topObjectsToCheck.add(topObject)

    molSystems = dataDict.get('molSystems')
    pass
    for molSystem in molSystems:
      topObject = molSystem.__dict__.get('topObject')
      topObjectsToCheck.add(topObject)

    probe = dataDict.get('probe')
    if (probe is not None):
      topObject = probe.__dict__.get('topObject')
      topObjectsToCheck.add(topObject)

    sample = dataDict.get('sample')
    if (sample is not None):
      topObject = sample.__dict__.get('topObject')
      topObjectsToCheck.add(topObject)

    spectrometer = dataDict.get('spectrometer')
    if (spectrometer is not None):
      topObject = spectrometer.__dict__.get('topObject')
      topObjectsToCheck.add(topObject)

    topObject = dataDict.get('topObject')
    topObjectsToCheck.add(topObject)
  
