  def _singleDelete(self, objsToBeDeleted):
    """
    singleDelete for ccp.nmr.Nmr.NmrProject:   deletes
    objects
    *Implementation function* - will CORRUPT DATA if called outside 
    the API delete function.
    """
    dataDict = self.__dict__
    dataDict['isDeleted'] = True
    memopsRoot = dataDict.get('memopsRoot')
    if (self is memopsRoot.__dict__.get('currentNmrProject')):
      memopsRoot.__dict__['currentNmrProject'] = None

    access = dataDict.get('access')
    if ((access is not None and not (access in objsToBeDeleted))):
      access.__dict__['dataObject'] = None

    for validationStore in dataDict.get('validationStores'):
      if (not (validationStore in objsToBeDeleted)):
        validationStore.__dict__['nmrProject'] = None

    memopsRoot = dataDict.get('memopsRoot')
    if (not (memopsRoot in objsToBeDeleted)):
      objKey = dataDict.get('name')
      if (objKey is None):
        raise ApiError("""%s._singleDelete:
         Key could not be calculated for object to be deleted""" % self.qualifiedName
        )
      else:
        dd = memopsRoot.__dict__.get('nmrProjects')
        if (self is dd.get(objKey)):
          del dd[objKey]

    dataDict['atomSets'] = {}
    dataDict['chainStateSets'] = {}
    dataDict['derivedDataLists'] = {}
    dataDict['experiments'] = {}
    dataDict['measurementLists'] = {}
    dataDict['nmrExpSeries'] = {}
    dataDict['peakClusters'] = {}
    dataDict['resonanceGroups'] = {}
    dataDict['resonanceSets'] = {}
    dataDict['resonances'] = {}
    dataDict['sampleConditionSets'] = {}
    dataDict['shiftReferences'] = {}
    dataDict['structureAnalyses'] = {}
    dataDict['structureGenerations'] = {}

