  def _checkDelete(self, objsToBeDeleted, objsToBeChecked, linkCounter, topObjectsToCheck):
    """
    checkDelete for ccp.nmr.Nmr.Peak:
       determines cascading deletes to 
    follow from delete of object.
       *Implementation function* - should be 
    called only by API delete function.
    """
    dataDict = self.__dict__
    objsToBeDeleted.add(self)
    if (not ((dataDict.get('topObject').__dict__.get('isLoaded') or dataDict.get('topObject').__dict__.get('isReading')))):
      dataDict.get('topObject').load()

    access = dataDict.get('access')
    if (access is not None):
      topObject = access.__dict__.get('topObject')
      topObjectsToCheck.add(topObject)

    xx1 = dataDict.get('topObject')
    if (xx1.__dict__.get('analysisProjectV3') is None):
      root = dataDict.get('topObject').__dict__.get('memopsRoot')
      root.refreshTopObjects('ccpnmr.AnalysisV3')

    tobj = xx1.__dict__.get('analysisProjectV3')
    if (tobj is not None):
      if (not (tobj.__dict__.get('isLoaded'))):
        tobj.load()

    analysisLayouts = dataDict.get('analysisLayouts')
    pass
    for analysisLayout in analysisLayouts:
      topObject = analysisLayout.__dict__.get('topObject')
      topObjectsToCheck.add(topObject)

    xx1 = dataDict.get('topObject')
    if (xx1.__dict__.get('analysisProjectV3') is None):
      root = dataDict.get('topObject').__dict__.get('memopsRoot')
      root.refreshTopObjects('ccpnmr.AnalysisV3')

    tobj = xx1.__dict__.get('analysisProjectV3')
    if (tobj is not None):
      if (not (tobj.__dict__.get('isLoaded'))):
        tobj.load()

    analysisPanels = dataDict.get('analysisPanels')
    pass
    for analysisPanel in analysisPanels:
      topObject = analysisPanel.__dict__.get('topObject')
      topObjectsToCheck.add(topObject)

    fitMethod = dataDict.get('fitMethod')
    if (fitMethod is not None):
      topObject = fitMethod.__dict__.get('topObject')
      topObjectsToCheck.add(topObject)

    peakContribs = dataDict.get('peakContribs').values()
    for peakContrib in peakContribs:
      if (not (peakContrib in objsToBeDeleted)):
        objsToBeDeleted.add(peakContrib)
        objsToBeChecked.append(peakContrib)

    peakDims = dataDict.get('peakDims').values()
    for peakDim in peakDims:
      if (not (peakDim in objsToBeDeleted)):
        objsToBeDeleted.add(peakDim)
        objsToBeChecked.append(peakDim)

    peakIntensities = dataDict.get('peakIntensities').values()
    for peakIntensity in peakIntensities:
      if (not (peakIntensity in objsToBeDeleted)):
        objsToBeDeleted.add(peakIntensity)
        objsToBeChecked.append(peakIntensity)

    peakValidations = dataDict.get('peakValidations')
    pass
    for peakValidation in peakValidations:
      topObject = peakValidation.__dict__.get('topObject')
      topObjectsToCheck.add(topObject)

    topObject = dataDict.get('topObject')
    topObjectsToCheck.add(topObject)
  
  def _singleDelete(self, objsToBeDeleted):
    """
    singleDelete for ccp.nmr.Nmr.Peak:   deletes objects
    *Implementation 
    function* - will CORRUPT DATA if called outside the API delete function.
    """
    dataDict = self.__dict__
    dataDict['isDeleted'] = True
    access = dataDict.get('access')
    if ((access is not None and not (access in objsToBeDeleted))):
      access.__dict__['dataObject'] = None

    for analysisLayout in dataDict.get('analysisLayouts'):
      if (not (analysisLayout in objsToBeDeleted)):
        currentPeaks = analysisLayout.__dict__.get('currentPeaks')
        currentPeaks.remove(self)

    for analysisPanel in dataDict.get('analysisPanels'):
      if (not (analysisPanel in objsToBeDeleted)):
        currentPeaks = analysisPanel.__dict__.get('currentPeaks')
        currentPeaks.remove(self)

    for dataDerivation in dataDict.get('dataDerivations'):
      if (not (dataDerivation in objsToBeDeleted)):
        peaks = dataDerivation.__dict__.get('peaks')
        peaks.remove(self)

    fitMethod = dataDict.get('fitMethod')
    if ((fitMethod is not None and not (fitMethod in objsToBeDeleted))):
      peaks = fitMethod.__dict__.get('peaks')
      peaks.remove(self)

    for measurement in dataDict.get('measurements'):
      if (not (measurement in objsToBeDeleted)):
        peaks = measurement.__dict__.get('peaks')
        peaks.remove(self)

    for peakCluster in dataDict.get('peakClusters'):
      if (not (peakCluster in objsToBeDeleted)):
        peaks = peakCluster.__dict__.get('peaks')
        peaks.remove(self)

    for peakValidation in dataDict.get('peakValidations'):
      if (not (peakValidation in objsToBeDeleted)):
        peaks = peakValidation.__dict__.get('peaks')
        peaks.remove(self)

    peakList = dataDict.get('peakList')
    if (not (peakList in objsToBeDeleted)):
      objKey = dataDict.get('serial')
      if (objKey is None):
        raise ApiError("""%s._singleDelete:
         Key could not be calculated for object to be deleted""" % self.qualifiedName
        )
      else:
        dd = peakList.__dict__.get('peaks')
        if (self is dd.get(objKey)):
          del dd[objKey]

