  def getByKey(startObj, fullKey):
    """
    GetByKey for ccp.nmr.Nmr.PeakDim
    """

    result = None
    if (startObj.__class__.__name__ == 'MemopsRoot'):
      if (6 != len(fullKey)):
        raise ApiError("""'ccp.nmr.Nmr.PeakDim'.getByKey:
         getByKey called with fullKey of wrong length. Parameters:"""
         + ": %s:%s" % (startObj, fullKey)
        )

      obj0 = startObj
      objKey = fullKey[0]
      obj1 = obj0.__dict__.get('nmrProjects').get(objKey)
      if (obj1 is None):
        obj0.refreshTopObjects('ccp.nmr.Nmr')
        obj1 = obj0.__dict__.get('nmrProjects').get(objKey)

    else:
      if (5 != len(fullKey)):
        raise ApiError("""'ccp.nmr.Nmr.PeakDim'.getByKey:
         getByKey called with fullKey of wrong length. Parameters:"""
         + ": %s:%s" % (startObj, fullKey)
        )

      obj1 = startObj

    if (obj1 is not None):
      if (not (obj1.__dict__.get('isLoaded'))):
        obj1.load()

      objKey = fullKey[-5]
      obj2 = obj1.__dict__.get('experiments').get(objKey)

      if (obj2 is not None):
        objKey = fullKey[-4]
        obj3 = obj2.__dict__.get('dataSources').get(objKey)

        if (obj3 is not None):
          objKey = fullKey[-3]
          obj4 = obj3.__dict__.get('peakLists').get(objKey)

          if (obj4 is not None):
            objKey = fullKey[-2]
            obj5 = obj4.__dict__.get('peaks').get(objKey)

            if (obj5 is not None):
              objKey = fullKey[-1]
              obj6 = obj5.__dict__.get('peakDims').get(objKey)
              result = obj6

    return result

