    if (value is None):
      raise ApiError("""%s.checkValid: isSimulated:
       value cannot be None""" % self.qualifiedName
       + ": %s" % (self,)
      )

    value = dataDict.get('name')
    # check roles
    value = dataDict.get('access')
    values = dataDict.get('analysisLayouts')
    values = dataDict.get('analysisPanels')
    value = dataDict.get('analysisPeakList')
    values = dataDict.get('analysisPeakLists')
    value = dataDict.get('dataSource')
    if (value is None):
      raise ApiError("""%s.checkValid: dataSource:
       value cannot be None""" % self.qualifiedName
       + ": %s" % (self,)
      )

    values = dataDict.get('entries')
    value = dataDict.get('fitMethod')
    value = dataDict.get('intensMethod')
    values = dataDict.get('peakListValidations')
    for value in values:
      ll= value.keywordDefinition.targetNames
      isValid = (not ll or self.qualifiedName in ll)
      if (not (isValid)):
        raise ApiError("""%s.checkValid: peakListValidations:
         peakListValidations constraint KeywordDefinition_fits_PeakList violated by value""" % self.qualifiedName
         + ": %s" % (value,)
        )

