  def _checkDelete(self, objsToBeDeleted, objsToBeChecked, linkCounter, topObjectsToCheck):
    """
    checkDelete for ccp.nmr.Nmr.DataDerivation:
       determines cascading 
    deletes to follow from delete of object.
       *Implementation function* - 
    should be called only by API delete function.
    """
    dataDict = self.__dict__
    objsToBeDeleted.add(self)
    if (not ((dataDict.get('topObject').__dict__.get('isLoaded') or dataDict.get('topObject').__dict__.get('isReading')))):
      dataDict.get('topObject').load()

    access = dataDict.get('access')
    if (access is not None):
      topObject = access.__dict__.get('topObject')
      topObjectsToCheck.add(topObject)

    derivedData_s = dataDict.get('derivedData').values()
    for derivedData in derivedData_s:
      if (not (derivedData in objsToBeDeleted)):
        objsToBeDeleted.add(derivedData)
        objsToBeChecked.append(derivedData)

    method = dataDict.get('method')
    if (method is not None):
      topObject = method.__dict__.get('topObject')
      topObjectsToCheck.add(topObject)

    topObject = dataDict.get('topObject')
    topObjectsToCheck.add(topObject)
  
  def _singleDelete(self, objsToBeDeleted):
    """
    singleDelete for ccp.nmr.Nmr.DataDerivation:   deletes
    objects
    *Implementation function* - will CORRUPT DATA if called outside 
    the API delete function.
    """
    dataDict = self.__dict__
    dataDict['isDeleted'] = True
    access = dataDict.get('access')
    if ((access is not None and not (access in objsToBeDeleted))):
      access.__dict__['dataObject'] = None

    for inputMeasurement in dataDict.get('inputMeasurements'):
      if (not (inputMeasurement in objsToBeDeleted)):
        dataDerivations = inputMeasurement.__dict__.get('dataDerivations')
        dataDerivations.remove(self)

    method = dataDict.get('method')
    if ((method is not None and not (method in objsToBeDeleted))):
      dataDerivations = method.__dict__.get('dataDerivations')
      dataDerivations.remove(self)

    for peakDim in dataDict.get('peakDims'):
      if (not (peakDim in objsToBeDeleted)):
        dataDerivations = peakDim.__dict__.get('dataDerivations')
        dataDerivations.remove(self)

    for peak in dataDict.get('peaks'):
      if (not (peak in objsToBeDeleted)):
        dataDerivations = peak.__dict__.get('dataDerivations')
        dataDerivations.remove(self)

    parentList = dataDict.get('parentList')
    if (not (parentList in objsToBeDeleted)):
      objKey = dataDict.get('serial')
      if (objKey is None):
        raise ApiError("""%s._singleDelete:
         Key could not be calculated for object to be deleted""" % self.qualifiedName
        )
      else:
        dd = parentList.__dict__.get('derivations')
        if (self is dd.get(objKey)):
          del dd[objKey]

