  def getByKey(startObj, fullKey):
    """
    GetByKey for ccp.nmr.Nmr.JCoupling
    """

    result = None
    if (startObj.__class__.__name__ == 'MemopsRoot'):
      if (4 != len(fullKey)):
        raise ApiError("""'ccp.nmr.Nmr.JCoupling'.getByKey:
         getByKey called with fullKey of wrong length. Parameters:"""
         + ": %s:%s" % (startObj, fullKey)
        )

      obj0 = startObj
      objKey = fullKey[0]
      obj1 = obj0.__dict__.get('nmrProjects').get(objKey)
      if (obj1 is None):
        obj0.refreshTopObjects('ccp.nmr.Nmr')
        obj1 = obj0.__dict__.get('nmrProjects').get(objKey)

    else:
      if (3 != len(fullKey)):
        raise ApiError("""'ccp.nmr.Nmr.JCoupling'.getByKey:
         getByKey called with fullKey of wrong length. Parameters:"""
         + ": %s:%s" % (startObj, fullKey)
        )

      obj1 = startObj

    if (obj1 is not None):
      if (not (obj1.__dict__.get('isLoaded'))):
        obj1.load()

      objKey = fullKey[-3]
      obj2 = obj1.__dict__.get('measurementLists').get(objKey)

      if (obj2 is not None):
        tempList = list()
        tempList.append(fullKey[-2])
        tempList.append(fullKey[-1])
        objKey = frozenset(tempList)
        obj3 = obj2.__dict__.get('measurements').get(objKey)
        result = obj3

    return result

